insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('3eedda97-43cc-433a-95d4-4bf4878958cd', 'es', 'Ella está metida en la conversación y la energía es buena. ¿Qué frase da por hecho el siguiente paso y mantiene el ritmo?', '["“Esto lo tenemos que repetir. Dame tu número.”", "“¿Te interesaría volver a verme?”", "“¿Estarías abierta a que saliéramos algún día?”", "“¿Creo que quizá deberíamos vernos?”"]'::jsonb, 'Trata su interés como algo ya establecido y propón el plan directamente.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('4051e636-695d-4534-936e-1f530668bf29', 'es', '¿Por qué demasiadas preguntas seguidas desequilibran la conversación?', '["La obligan a hacer casi todo el trabajo", "Se sienten como un interrogatorio y no como algo compartido", "Muestran que estás prestando atención"]'::jsonb, 'Las preguntas una tras otra crean un desequilibrio en el que uno da y el otro solo recibe.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('4533a8d2-717d-49b4-b4a9-c89b28985777', 'es', 'Te dice: “Acabo de volver de un viaje a Japón”. ¿Qué podrías decir después?', '["Contarle tus propias experiencias de viaje", "Preguntarle: “¿Qué fue lo que más te gustó de Japón?”", "Cambiar de tema y preguntarle dónde vive", "Felicitarla por viajar"]'::jsonb, 'Retomar el hilo construye sobre su detalle para profundizar la conversación con naturalidad.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('48b2d089-1b51-4e26-9f2f-517c02891e1b', 'es', '¿Qué comportamientos indican interés de forma no verbal?', '["Estar de frente a ella mientras habla", "Una expresión neutra todo el tiempo", "Un contacto visual natural", "Asentir sutilmente en los momentos clave"]'::jsonb, 'La orientación, el contacto visual y los gestos de respuesta comunican presencia.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('497c00d6-116b-4bf7-9ccf-9fdbef04ef82', 'es', 'Te da una respuesta corta sobre su familia y la energía baja. ¿Qué podrías hacer?', '["Hacerle otra pregunta sobre su familia", "Cambiar de tema con ligereza: “Oye, ¿qué tal está tu comida?”", "Disculparte por el momento incómodo", "Preguntarle por qué respondió tan corto"]'::jsonb, 'Reconduce con calma hacia un terreno neutro para recuperar el ritmo sin presión.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('4cd2af01-a10e-4c9e-b164-6c82a959ca1f', 'es', '¿Por qué insistir en demostrar que tienes razón debilita la conexión?', '["Convierte la conversación en una competencia", "Transmite que te importa más tener razón que conectar", "Muestra que tienes conciencia social", "La hace sentir equivocada en lugar de simplemente distinta"]'::jsonb, 'No es el desacuerdo lo que genera tensión, sino la necesidad de demostrar algo.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('4d5ba9c1-712a-4d9d-b8a1-4ffec08ad96c', 'es', '¿Qué cambio de mentalidad te permite escuchar para entender?', '["Preparar respuestas ingeniosas de antemano", "Estar plenamente presente sin planear lo que viene", "Fijarte en cómo tus historias encajan con las suyas", "Reaccionar rápido para mantener la energía"]'::jsonb, 'Estar presente exige soltar las respuestas planeadas de antemano.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('4e01d376-3513-4958-b45f-3cbac7198e67', 'es', 'Tuvieron una gran charla sobre su próximo viaje a Portugal. Es hora de irte. ¿Qué podrías decir?', '["“Un gusto hablar contigo, que tengas un gran día.”", "“Portugal suena increíble. Me tienes que contar cómo te va.”", "“Buen viaje cuando vayas.”"]'::jsonb, 'Termina con una referencia concreta para dar continuidad y un motivo natural para volver a hablar.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('4e138ced-bcd3-4f4b-9394-d046b4bd81e7', 'es', 'Te dice que quiere probar una cafetería que le recomendaste. ¿Qué propuestas pequeñas funcionan bien?', '["“Deberíamos ir juntos esta semana. ¿Estás libre el sábado?”", "“Te paso la dirección. ¿Cuál es tu número?”", "“Avísame qué tal cuando vayas”"]'::jsonb, 'Las propuestas sin presión bajan las defensas; pide poco para que el sí salga natural.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('52c57688-6476-42cc-9677-4cb5e66512fd', 'es', 'Te pregunta: “¿Por qué terminó tu última relación?”. ¿Qué respuesta es más serena?', '["“Me hizo mucho daño y todavía lo estoy procesando.”", "“Fue tóxica y me dejó muy mal.”", "“Queríamos cosas distintas, y me enseñó qué es lo que más valoro ahora.”"]'::jsonb, 'Reconoce la realidad y a la vez muestra perspectiva. Despierta curiosidad, no preocupación.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('535c49aa-9750-45dd-9796-69f61c22aedf', 'es', '¿Qué comportamientos indican que alguien escucha para responder y no para entender?', '["Reflejar lo que ella contó", "Saltar rápido a dar consejos", "Interrumpir antes de que termine", "Respuestas que no conectan con lo último que dijo"]'::jsonb, 'Estos comportamientos muestran que el foco está en lucirse o controlar, no en entender.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('58d8c403-8e7d-4168-b8ba-758c4dff889c', 'es', 'Te dice: “Acabo de volver de un viaje a Japón”. ¿Qué podrías decir después?', '["Contarle tus propias experiencias de viaje", "Preguntarle: “¿Qué fue lo que más te gustó de Japón?”", "Cambiar de tema y preguntarle dónde vive", "Felicitarla por viajar"]'::jsonb, 'Retomar el hilo construye sobre su detalle para profundizar la conversación con naturalidad.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('59ddb591-0f25-456d-abef-ddcf1bc55c9f', 'es', 'Te cuenta un percance gracioso de un viaje. ¿Qué podría hacer la historia con la que respondes?', '["Acompañarla con una anécdota graciosa parecida", "Contar toda tu historia de viajes", "Saltar a un tema completamente distinto", "Dar un consejo en lugar de compartir"]'::jsonb, 'Mantenla breve y bien estructurada para reflejar su energía y crear conexión.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('5def4588-2c49-4e7d-a78b-6de3a668455b', 'es', '¿Por qué demasiadas preguntas crean un desequilibrio en la conversación?', '["Sacas información sin aportar nada a cambio", "Las preguntas la presionan para que se luzca y te entretenga", "Las dos anteriores"]'::jsonb, 'Las preguntas una tras otra crean un desequilibrio en el que uno da y el otro solo recibe.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('6309d2eb-7004-43f3-99ec-c276acb5ec61', 'es', 'Sostiene la mirada y te hace preguntas de seguimiento. ¿Qué indica esto?', '["Está distraída y quiere terminar la charla", "Primero hace falta más charla casual", "Está siendo cortés, pero no le interesas", "Está implicada y es momento de concretar"]'::jsonb, 'Una curiosidad activa y un lenguaje corporal positivo muestran que es momento de concretar.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('65941383-8920-456d-9564-8f938de86fed', 'es', '¿Qué comportamientos te ayudan a no estar de acuerdo sin desconectar?', '["Presentar tu punto de vista como verdad absoluta", "Hacerle preguntas sobre su razonamiento", "Mantener un tono tranquilo", "Dejar que existan las dos perspectivas"]'::jsonb, 'La conexión sobrevive cuando las diferencias se exploran, no cuando se descalifican.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('66cbe1b3-1585-4d3f-b00f-bb1fcf3143d3', 'es', '¿Qué pasa cuando sigues adelante sin reconocer lo que dijo?', '["Te hace sonar apresurado", "Da a entender que quizá no entendiste su mensaje", "Reduce los temas de conversación", "Frena el ritmo"]'::jsonb, 'Reconocer lo que dijo muestra que entendiste; hazlo antes de la siguiente pregunta.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('674acf71-26d4-428e-aa33-571e27f0d7d7', 'es', '¿Qué hace que retomar hilos se sienta más natural que saltar de tema en tema?', '["Se parece a cómo hablan de verdad los amigos", "La conversación se construye sobre sí misma en lugar de parecer aleatoria", "Ella se siente escuchada porque respondes a lo que te cuenta", "Se construye sobre sí misma y ella se siente escuchada"]'::jsonb, 'Retomar hilos crea fluidez; cada respuesta se construye sobre la anterior.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('68abae72-376e-4c38-bd5f-a63ad5d4ed56', 'es', 'Te cuenta brevemente que acaba de cumplir una entrega muy estresante en el trabajo. ¿Qué respondes?', '["Reconocerlo y luego contarle un reto parecido que superaste en el trabajo", "Darle de inmediato consejos de carrera", "Pasar a hablar de tus planes para el fin de semana"]'::jsonb, 'Acompaña su energía con una historia breve y relevante para crear conexión.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('6a3257d1-17bb-4df3-b9ca-c907755b7988', 'es', '¿Qué hace buena una historia al principio de una conversación?', '["Elegir un momento concreto con impacto emocional", "Incluir todos los detalles posibles", "Relatar los hechos tal como los recuerdas", "Alargarla para mostrar profundidad"]'::jsonb, 'Una imagen breve de lo que importó crea conexión más rápido que toda la historia completa.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('72a6b099-3278-4a37-8a82-51225280d333', 'es', '¿Qué crea anclas emocionales positivas?', '["La risa genuina: no por cortesía, sino alegría de verdad", "El reconocimiento: reconocer lo que a ella le importa", "La curiosidad: hacer que piense distinto sobre sí misma", "Todas las anteriores"]'::jsonb, 'El reconocimiento, la curiosidad y la risa hacen avanzar la emoción.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('75148042-557e-4fcd-b9cf-a733e31a8702', 'es', 'Te dice: “Acabo de visitar a mi hermana en Guadalajara”. ¿Qué podrías decir después?', '["“¿Viajas mucho?”", "“Qué bien que seas tan cercana a tu hermana. ¿Qué hicieron?”", "“Guadalajara es genial. ¿Conoces Monterrey?”", "“¿Cuánto duró el viaje?”"]'::jsonb, 'Primero reconoce su experiencia para mostrar que la entiendes antes de construir sobre ella.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('75dbf155-f762-4c46-a881-ee4691d19f29', 'es', '¿Qué mentalidad lleva en general a concretar mejor?', '["“Tengo que asegurar algo”", "“Esto tiene que llevar a algo”", "“Ahora o nunca”", "“Demos un pequeño paso hacia delante”"]'::jsonb, 'Los pasos pequeños bajan las defensas; pide poco para que el sí salga natural.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('76af82d7-0b8b-4c02-ad43-4cff911e6e4f', 'es', '¿Qué mentalidad lleva en general a mejores despedidas?', '["Estar atento a los hilos que puedes retomar después", "Esperar que el momento sea el adecuado", "Intentar que te recuerde", "Terminar rápido para evitar momentos incómodos"]'::jsonb, 'Relacionarla con un hilo de la conversación te da un motivo natural para volver a conectar.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('79854e99-6c36-4456-94b9-a4a09f901b6e', 'es', '¿Por qué el reconocimiento crea seguridad psicológica?', '["La gente siente que sus experiencias se reconocen y se entienden", "Demuestra inteligencia emocional y empatía", "El reconocimiento hace que la gente se sienta importante y valorada"]'::jsonb, 'Cuando se siente entendida, se abre con más naturalidad.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('7f4038e9-35fa-4928-b87c-513fe0b81ce9', 'es', 'Después de que te cuenta que tuvo un día estresante, ¿qué deberías evitar?', '["Decir: “Este lugar siempre me relaja después de un día largo.”", "Preguntar: “¿Qué hizo que tu día fuera tan estresante?”", "Comentar: “Pareces alguien que maneja bien el estrés.”"]'::jsonb, 'Haz que te asocie con emociones positivas; no la interrogues sobre su estrés.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('8105c1a4-951f-4041-9374-fb7c65a70dca', 'es', '¿Qué hilos te da la frase “Soy abogada”?', '["Su puesto concreto y sus responsabilidades", "El tipo de derecho al que se dedica", "Su experiencia laboral y su trayectoria", "Todas las anteriores"]'::jsonb, 'Retomar el hilo significa profundizar en su tema; pregunta detalles sobre lo que mencionó.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('8389bf63-7797-4fed-8bf2-0f7cb7b996c7', 'es', 'La conversación fluye y ella se está riendo. ¿Qué podrías decir para dar por hecho el siguiente paso?', '["“¿Te gustaría, no sé, tomar un café algún día?”", "“No sé, pero ¿quizá podríamos vernos?”", "“¿Quieres que intercambiemos números?”", "“Vamos a tomar un café. ¿Cuál es tu número?”"]'::jsonb, 'Di el siguiente paso con seguridad, como un hecho, en lugar de pedir permiso.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('8424db00-09f4-4aa8-b16b-d90b7a683c0b', 'es', '¿Por qué los monólogos largos reducen la atracción?', '["Suenan ensayados", "Le quitan la oportunidad de implicarse", "Hacen más lenta la conversación", "Revelan demasiado"]'::jsonb, 'Cuando no puede aportar, se implica menos. Dale espacio para compartir.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('8578c723-b332-450d-8dd1-4eaad1b6150b', 'es', '¿Por qué deberías conectar tu historia con su mundo?', '["Crea un intercambio compartido en lugar de historias en paralelo", "Muestra que usas la historia para entenderla", "Evita que la conversación se sienta desconectada", "Todas las anteriores"]'::jsonb, 'Conectarla convierte la historia en una herramienta de conexión, no solo en un número para lucirte.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('87339858-15ab-4a2b-89af-d6a42cafac7a', 'es', '¿Qué logran las frases de reconocimiento?', '["Muestran que sus palabras de verdad te llegaron", "Abren espacio para un intercambio más genuino", "Demuestran seguridad y conciencia emocional", "La mantienen en el momento, sintiéndose entendida"]'::jsonb, 'Reconocer sus palabras muestra que las escuchaste, y eso invita a compartir más a fondo.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('97b34e22-5615-4aa3-bf23-73f5718f67c6', 'es', '¿Qué acciones ayudan a convertir una historia en conexión y no en un callejón sin salida?', '["Terminar contando lo impresionante que fue el resultado", "Preguntarle cómo se identifica ella con la situación", "Relacionar la historia con algo que ella ya mencionó"]'::jsonb, 'Las historias conectan cuando invitan su mundo a la conversación.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('97e7b932-511e-48e1-bf8b-9b0e49bd18f9', 'es', 'Ella está hablando y te das cuenta de que estás planeando tu respuesta. ¿Qué deberías hacer?', '["Terminar de planear rápido y luego volver a lo que dice", "Dejar de planear y volver ya a poner toda tu atención en sus palabras", "Pedirle que repita lo último porque te distrajiste"]'::jsonb, 'Date cuenta de que te fuiste y vuelve de inmediato a sus palabras y a su tono.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('998825a4-01bc-40bc-9219-b9e8a227feb8', 'es', 'Notas tensión después de dar una opinión distinta. ¿Cuál es el giro más limpio?', '["Suavizar el tono y preguntarle por su experiencia", "Insistir con más argumentos", "Disculparte por no estar de acuerdo"]'::jsonb, 'Pasa de demostrar a entender; invítala a contar su experiencia.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('9a3ada69-efcb-4e14-96d0-7d4c087e2d2a', 'es', '¿Qué aportan sobre todo las observaciones y los comentarios a una conversación?', '["Equilibran el intercambio", "Revelan tu propio punto de vista", "La obligan a responder"]'::jsonb, 'Hacen que la interacción se sienta compartida y cálida.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('9b82f398-1878-449a-baf9-24e1e9ec6c0d', 'es', '¿Por qué compartir algo procesado crea conexión?', '["Muestra autoconocimiento y crecimiento personal", "Muestra vulnerabilidad sin cargarla emocionalmente", "Invita a la cercanía sin que se sienta obligada a ayudarte", "Todas las anteriores"]'::jsonb, 'Cuando las experiencias están procesadas, invitan a conectar y no a cuidar de ti.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('9bb0ed54-392a-4aab-9aed-715508c1df96', 'es', 'No estás de acuerdo con su opinión sobre una película. Ella parece apasionada. ¿Qué podrías hacer?', '["Explicarle por qué su opinión tiene fallos", "Decirle: “Qué buena forma de verlo. ¿Por qué te encanta tanto?”", "Hacer como que estás de acuerdo para que todo fluya", "Pasar de inmediato a otro tema"]'::jsonb, 'Muestra curiosidad por lo que la apasiona para seguir conectados a pesar de las diferencias.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('9d4b7485-9598-45ab-9df1-95a6de8dbd91', 'es', 'Te dice: “Esta semana he trabajado hasta tarde todas las noches”. ¿Qué podrías decir después?', '["“¿A qué te dedicas?”", "“Suena a que te ganaste de sobra una noche de salida.”", "“¿Cuántas horas trabajas?”", "“¿Estás cansada?”"]'::jsonb, 'Un comentario aporta algo y la invita a compartir sin presión.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('9f096c93-c6af-4940-a92a-503d7c7f4a16', 'es', 'Te cuenta que le está costando su nuevo trabajo. Compartes tu propia experiencia. ¿Y después?', '["“Eso me pasó a mí también. En fin…”", "“¿Y tú cómo te estás adaptando hasta ahora?”", "“¿Y a qué te dedicas exactamente?”"]'::jsonb, 'Conecta con su situación actual para invitar su punto de vista y profundizar la conexión.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('9f811f6d-ea33-440c-a2f7-4e4f2eab4134', 'es', 'Te dice que está estresada por el trabajo. ¿Qué respuesta crea una asociación positiva?', '["“Suena difícil. El trabajo es durísimo.”", "“Deberías organizar mejor tu tiempo.”", "“Hoy en día todo el mundo está estresado.”", "“¿Qué es lo que más ganas tienes de hacer cuando termine?”"]'::jsonb, 'Esto lleva con suavidad su estado emocional del estrés al alivio y la ilusión.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('a3852cf6-c43a-47f6-95c6-432c2afa408f', 'es', 'Van caminando juntos y la conversación se apaga. ¿Qué indica un buen reinicio?', '["Una pausa relajada antes de reconducir", "Cambiar de tema muy rápido", "Preguntarle si se está aburriendo"]'::jsonb, 'La calma comunica más seguridad que la prisa.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
